<?php
declare(strict_types=1); namespace OCA\ERP\Service;
use OCA\ERP\Db\MeasurementBlock; use OCA\ERP\Db\MeasurementBlockMapper;
class MeasurementBlockService { public function __construct(private MeasurementBlockMapper $mapper,private MeasurementRecordService $records,private MeasurementBlockValidator $validator,private MeasurementAssetService $assets){} /** @return list<MeasurementBlock> */ public function list(int $recordId):array{$this->records->get($recordId);return $this->mapper->findByRecord($recordId);} /** @param array<string,mixed> $payload */ public function create(int $recordId,string $type,array $payload):MeasurementBlock{$this->records->assertDraft($recordId);$payload=$this->validated($recordId,$type,$payload);$now=time();$b=new MeasurementBlock();$b->setMeasurementRecordId($recordId);$b->setUuid($this->uuid());$b->setBlockType($type);$b->setPayload(json_encode($payload,JSON_THROW_ON_ERROR));$b->setPosition(count($this->mapper->findByRecord($recordId))+1);$b->setVersion(1);$b->setCreatedAt($now);$b->setUpdatedAt($now);return $this->mapper->insert($b);} /** @param array<string,mixed> $payload */ public function update(int $recordId,int $id,array $payload):MeasurementBlock{$this->records->assertDraft($recordId);$b=$this->block($recordId,$id);$b->setPayload(json_encode($this->validated($recordId,$b->getBlockType(),$payload),JSON_THROW_ON_ERROR));$b->setVersion($b->getVersion()+1);$b->setUpdatedAt(time());return $this->mapper->update($b);} public function delete(int $recordId,int $id):MeasurementBlock{$this->records->assertDraft($recordId);$b=$this->block($recordId,$id);$b->setDeletedAt(time());$b->setUpdatedAt(time());$b->setVersion($b->getVersion()+1);return $this->mapper->update($b);} /** @param list<int> $ids @return list<MeasurementBlock> */ public function reorder(int $recordId,array $ids):array{$this->records->assertDraft($recordId);$blocks=$this->mapper->findByRecord($recordId);$actual=array_map(fn($b)=>$b->getId(),$blocks);sort($actual);$requested=$ids;sort($requested);if($actual!==$requested)throw new \InvalidArgumentException('blockIds must contain every active block exactly once');$byId=[];foreach($blocks as $b)$byId[$b->getId()]=$b;foreach($ids as $position=>$id){$b=$byId[$id];$b->setPosition($position+1);$b->setVersion($b->getVersion()+1);$b->setUpdatedAt(time());$this->mapper->update($b);}return $this->mapper->findByRecord($recordId);} private function block(int $recordId,int $id):MeasurementBlock{$b=$this->mapper->findById($id);if($b===null||$b->getMeasurementRecordId()!==$recordId||$b->getDeletedAt()!==null)throw new \OutOfBoundsException('Measurement block not found');return $b;} private function validated(int $recordId,string $type,array $payload):array{$payload=$this->validator->validate($type,$payload);if($type==='image'||$type==='plan')$this->assets->assertOwned($this->records->get($recordId)->getProjectId(),$payload['assetFileId'],$payload['mimeType']);return $payload;} private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
